def choose_move(observation):
    # Defensive access to observation data with defaults.
    grid = observation.get('grid', [])
    agent_pos = observation.get('agent', {}).get('position', (0, 0))
    width = len(grid[0]) if grid else 0
    height = len(grid)

    # Directions: (dx, dy)
    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    # Helper to check in bounds
    def in_bounds(x, y):
        return 0 <= x < width and 0 <= y < height

    # Helper to get cell safely
    def get_cell(x, y):
        if in_bounds(x, y):
            return grid[y][x]
        return None

    x, y = agent_pos

    # Recognize possible goals based on observation structure.
    # Resource collection: look for resource tiles.
    # Pursuit-evasion: look for evaders.
    # Territory control: look for neutral or enemies.

    # Strategy:
