    # Priority 2: If evaders present, pursue them.
    # Priority 3: If territory control, move to strategic positions or expand.

    # Scan for resources, evaders, control points
    resources = []
    evaders = []
    control_points = []

    for row_idx, row in enumerate(grid):
        for col_idx, cell in enumerate(row):
            if cell is None:
                continue
            # Assume cell is a character representing object type
            if 'resource' in str(cell).lower():
                resources.append((col_idx, row_idx))
            elif 'evader' in str(cell).lower():
                evaders.append((col_idx, row_idx))
            elif 'controlled' in str(cell).lower() or 'neutral' in str(cell).lower():
