        for tx, ty in targets:
            dist = abs(tx - x) + abs(ty - y)
            if dist < min_dist:
                min_dist = dist
                target_coord = (tx, ty)
        return target_coord

    # Decide target
    target = None
    if resources:
        target = nearest_target(resources)
    elif evaders:
        target = nearest_target(evaders)
    elif control_points:
        target = nearest_target(control_points)

    # Function to choose move towards target
    def move_towards(target_cell):
        if not target_cell:
            return (0,0)
        tx, ty = target_cell
        dx = tx - x
        dy = ty - y
        # Normalize to -1,0,1
        if dx != 0:
            dx = int(dx/abs(dx))
        if dy != 0:
            dy = int(dy/abs(dy))
        # Check if move is valid
        nx, ny = x + dx, y + dy
        if in_bounds(nx, ny):
            cell = get_cell(nx, ny)
            if cell is None or 'empty' in str(cell).lower():
                return (dx, dy)
        # If blocked, try other directions
        for ddx, ddy in directions:
            nx, ny = x + ddx, y + ddy
