                cell = get_cell(nx, ny)
                if cell is None or 'empty' in str(cell).lower():
                    return (ddx, ddy)
        return (0,0)

    # Execute move if target exists
    if target:
        dx, dy = move_towards(target)
        return [dx, dy]
    else:
        # Default fallback: stay in place
        return [0,0]
